//! Cross-build compatibility for binaries without an exact Patch-DB md5.
//!
//! The profile bank is generated by `patchdb/find_offsets.py` from builds with
//! known tables. A site is accepted only after its expected or already-patched
//! bytes are verified at the resolved offset. Any unresolved site stays a
//! mismatch, so [`crate::patch_engine::apply`] aborts before writing.

use std::cmp::Reverse;
use std::collections::BTreeMap;
use std::sync::OnceLock;

use serde::Deserialize;

use crate::patch_engine::{EngineError, Resolved, decode_hex, parse_aob, scan_all};
use crate::tables::{PatchDb, Table, TableSite};

const PROFILE_SCHEMA: &str = "stereo-wizard-offset-profiles-v1";
const MAX_HITS: usize = 4096;

#[derive(Debug, Deserialize)]
struct ProfileBank {
    schema: String,
    goal: String,
    profiles: Vec<Profile>,
}

#[derive(Debug, Deserialize)]
struct Profile {
    #[serde(default)]
    sites: Vec<ProfileSite>,
}

#[derive(Debug, Deserialize)]
struct ProfileSite {
    name: String,
    #[serde(default)]
    aliases: Vec<String>,
    pattern: String,
    #[serde(default)]
    target_offset: usize,
    #[serde(default)]
    expected: String,
    #[serde(default)]
    patch: String,
    #[serde(default)]
    source_md5: Option<String>,
    #[serde(default)]
    kind: String,
}

static BANK: OnceLock<Option<ProfileBank>> = OnceLock::new();

fn bank() -> Option<&'static ProfileBank> {
    BANK.get_or_init(|| {
        let raw = include_str!("../../patchdb/offset_profiles.json");
        let parsed: ProfileBank = serde_json::from_str(raw).ok()?;
        (parsed.schema == PROFILE_SCHEMA).then_some(parsed)
    })
    .as_ref()
}

/// Latest offset table for a goal that matches the host OS and architecture.
///
/// Pattern-only tables are excluded: they are already tried by the normal
/// engine path and do not need cross-build relocation.
pub fn table_for<'a>(db: &'a PatchDb, goal: &str) -> Option<&'a Table> {
    let os = std::env::consts::OS;
    let arch = std::env::consts::ARCH;
    let mut tables: Vec<&Table> = db
        .tables
        .iter()
        .filter(|t| t.goal == goal && t.binary_md5.is_some())
        .filter(|t| {
            t.sites
                .iter()
                .all(|s| matches!(s, TableSite::Offset { .. }))
        })
        .filter(|t| t.os.as_deref().is_none_or(|value| value == os))
        .filter(|t| t.arch.as_deref().is_none_or(|value| value == arch))
        .collect();
    tables.sort_by_key(|t| version_key(t));
    tables.pop()
}

fn version_key(table: &Table) -> u64 {
    table
        .discord
        .as_deref()
        .and_then(|label| label.rsplit('.').next())
        .and_then(|value| value.parse().ok())
        .unwrap_or(0)
}

/// Resolve every offset site against a foreign build.
pub fn resolve(table: &Table, bytes: &[u8]) -> Result<Vec<Resolved>, EngineError> {
    let profiles = bank().filter(|bank| bank.goal == table.goal);
    resolve_with_bank(table, bytes, profiles)
}

struct Work {
    name: String,
    ref_offset: u32,
    orig: Vec<u8>,
    patch: Vec<u8>,
    result: Option<u32>,
    reason: Option<String>,
}

impl Work {
    fn matches_orig(&self, bytes: &[u8], offset: u32) -> bool {
        let start = offset as usize;
        bytes.get(start..start + self.orig.len()) == Some(self.orig.as_slice())
    }

    fn matches_patch(&self, bytes: &[u8], offset: u32) -> bool {
        let start = offset as usize;
        bytes.get(start..start + self.patch.len()) == Some(self.patch.as_slice())
    }

    fn resolve_at(&mut self, offset: u32) {
        self.result = Some(offset);
        self.reason = None;
    }
}

fn resolve_with_bank(
    table: &Table,
    bytes: &[u8],
    profiles: Option<&ProfileBank>,
) -> Result<Vec<Resolved>, EngineError> {
    let mut sites = Vec::with_capacity(table.sites.len());
    for site in &table.sites {
        let TableSite::Offset {
            name,
            offset,
            orig,
            patch,
        } = site
        else {
            sites.push(Work {
                name: site.name().to_owned(),
                ref_offset: 0,
                orig: Vec::new(),
                patch: Vec::new(),
                result: None,
                reason: Some("compat: pattern-only site".into()),
            });
            continue;
        };
        let Some(ref_offset) = parse_offset(offset) else {
            sites.push(Work {
                name: name.clone(),
                ref_offset: 0,
                orig: Vec::new(),
                patch: Vec::new(),
                result: None,
                reason: Some("compat: invalid offset".into()),
            });
            continue;
        };
        sites.push(Work {
            name: name.clone(),
            ref_offset,
            orig: decode_hex(orig, name)?,
            patch: decode_hex(patch, name)?,
            result: None,
            reason: None,
        });
    }

    for site in &mut sites {
        if site.reason.is_some() || site.orig.is_empty() {
            continue;
        }
        if site.matches_orig(bytes, site.ref_offset) || site.matches_patch(bytes, site.ref_offset) {
            site.resolve_at(site.ref_offset);
        }
    }

    if let Some(bank) = profiles {
        let ref_md5 = table.binary_md5.as_deref().unwrap_or_default();
        for site in &mut sites {
            if site.result.is_some() || site.reason.is_some() || site.orig.is_empty() {
                continue;
            }
            let entries = profile_entries(bank, &site.name, ref_md5);
            let (valid, patched) = candidates(site, bytes, &entries);
            match (valid.len(), patched.len()) {
                (1, _) => site.resolve_at(*valid.keys().next().expect("one valid offset")),
                (0, 1) => site.resolve_at(*patched.keys().next().expect("one patched offset")),
                (0, 0) => {}
                (valid_count, patched_count) => {
                    site.reason = Some(format!(
                        "compat: ambiguous ({valid_count} valid, {patched_count} patched)"
                    ));
                }
            }
        }
    }

    for site in &mut sites {
        if site.result.is_some() || site.reason.is_some() || site.orig.len() < 4 {
            continue;
        }
        let hits = find_all_exact(bytes, &site.orig, 2);
        if hits.len() == 1 {
            site.resolve_at(hits[0] as u32);
        }
    }

    let mut anchors: Vec<usize> = sites
        .iter()
        .enumerate()
        .filter_map(|(index, site)| site.result.map(|_| index))
        .collect();
    anchors.sort_unstable();
    for index in 0..sites.len() {
        if sites[index].result.is_some() || sites[index].reason.is_some() {
            continue;
        }
        let mut estimates: BTreeMap<u32, bool> = BTreeMap::new();
        for &anchor_index in &anchors {
            let anchor = &sites[anchor_index];
            let Some(anchor_offset) = anchor.result else {
                continue;
            };
            let delta = i64::from(sites[index].ref_offset) - i64::from(anchor.ref_offset);
            let estimate = i64::from(anchor_offset) + delta;
            let Ok(estimate) = u32::try_from(estimate) else {
                continue;
            };
            if sites[index].matches_orig(bytes, estimate) {
                estimates.insert(estimate, false);
            } else if sites[index].matches_patch(bytes, estimate) {
                estimates.insert(estimate, true);
            }
        }
        if estimates.len() == 1 {
            let offset = *estimates.keys().next().expect("one relative offset");
            sites[index].resolve_at(offset);
        }
    }

    for site in &mut sites {
        if site.result.is_none() && site.reason.is_none() {
            site.reason = Some("compat: no verified match".into());
        }
    }

    Ok(sites
        .into_iter()
        .map(|site| Resolved {
            name: site.name,
            offset: site.result.unwrap_or(0),
            orig: site.orig,
            patch: site.patch,
            reason: site.reason,
        })
        .collect())
}

fn parse_offset(value: &str) -> Option<u32> {
    u32::from_str_radix(value.trim().trim_start_matches("0x"), 16).ok()
}

fn profile_entries<'a>(bank: &'a ProfileBank, name: &str, ref_md5: &str) -> Vec<&'a ProfileSite> {
    let mut entries = Vec::new();
    for profile in &bank.profiles {
        for site in &profile.sites {
            if site.name == name || site.aliases.iter().any(|alias| alias == name) {
                entries.push(site);
            }
        }
    }
    entries.sort_by_key(|site| Reverse(priority(site, ref_md5)));
    entries
}

fn priority(site: &ProfileSite, ref_md5: &str) -> u8 {
    if site.kind == "consensus" {
        3
    } else if site.source_md5.as_deref() == Some(ref_md5) {
        2
    } else {
        1
    }
}

fn candidates(
    site: &Work,
    bytes: &[u8],
    entries: &[&ProfileSite],
) -> (BTreeMap<u32, ()>, BTreeMap<u32, ()>) {
    let mut valid = BTreeMap::new();
    let mut patched = BTreeMap::new();
    for entry in entries {
        let Some(expected) = decode_hex(&entry.expected, &entry.name).ok() else {
            continue;
        };
        let Some(patch) = decode_hex(&entry.patch, &entry.name).ok() else {
            continue;
        };
        if expected != site.orig || patch != site.patch {
            continue;
        }
        let Some(aob) = parse_aob(&entry.pattern) else {
            continue;
        };
        for hit in scan_all(bytes, &aob, MAX_HITS) {
            let Some(target) = hit.checked_add(entry.target_offset) else {
                continue;
            };
            let Ok(offset) = u32::try_from(target) else {
                continue;
            };
            if site.matches_orig(bytes, offset) {
                valid.insert(offset, ());
            } else if site.matches_patch(bytes, offset) {
                patched.insert(offset, ());
            }
        }
    }
    (valid, patched)
}

fn find_all_exact(bytes: &[u8], needle: &[u8], limit: usize) -> Vec<usize> {
    let mut hits = Vec::new();
    if needle.is_empty() || needle.len() > bytes.len() {
        return hits;
    }
    let finder = memchr::memmem::Finder::new(needle);
    let mut pos = 0;
    while let Some(found) = finder.find(&bytes[pos..]) {
        hits.push(pos + found);
        if hits.len() >= limit {
            break;
        }
        pos += found + 1;
    }
    hits
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::tables::TableSite;

    fn table(sites: Vec<TableSite>) -> Table {
        Table {
            binary_md5: Some("0123456789abcdef0123456789abcdef".into()),
            discord: Some("app-1.0.9266".into()),
            os: Some("windows".into()),
            arch: Some("x86_64".into()),
            goal: "v6".into(),
            sites,
        }
    }

    fn offset_site(name: &str, offset: u32, orig: &[u8], patch: &[u8]) -> TableSite {
        TableSite::Offset {
            name: name.into(),
            offset: format!("0x{offset:x}"),
            orig: hex::encode(orig),
            patch: hex::encode(patch),
        }
    }

    fn profile_site(
        name: &str,
        pattern: &str,
        target_offset: usize,
        orig: &[u8],
        patch: &[u8],
    ) -> ProfileSite {
        ProfileSite {
            name: name.into(),
            aliases: Vec::new(),
            pattern: pattern.into(),
            target_offset,
            expected: hex::encode(orig),
            patch: hex::encode(patch),
            source_md5: None,
            kind: "consensus".into(),
        }
    }

    fn bank(sites: Vec<ProfileSite>) -> ProfileBank {
        ProfileBank {
            schema: PROFILE_SCHEMA.into(),
            goal: "v6".into(),
            profiles: vec![Profile { sites }],
        }
    }

    #[test]
    fn fixed_offset_still_wins_on_a_foreign_build() {
        let table = table(vec![offset_site(
            "site",
            0x100,
            &[0xaa, 0xbb, 0xcc, 0xdd],
            &[0x11, 0x22, 0x33, 0x44],
        )]);
        let mut bytes = vec![0u8; 0x200];
        bytes[0x100..0x104].copy_from_slice(&[0xaa, 0xbb, 0xcc, 0xdd]);
        let resolved = resolve_with_bank(&table, &bytes, None).unwrap();
        assert_eq!(resolved[0].offset, 0x100);
        assert!(resolved[0].reason.is_none());
    }

    #[test]
    fn profile_pattern_relocates_the_site() {
        let table = table(vec![offset_site(
            "site",
            0x100,
            &[0xaa, 0xbb, 0xcc, 0xdd],
            &[0x11, 0x22, 0x33, 0x44],
        )]);
        let mut bytes = vec![0u8; 0x200];
        bytes[0x150..0x154].copy_from_slice(&[0xaa, 0xbb, 0xcc, 0xdd]);
        let bank = bank(vec![profile_site(
            "site",
            "00 00 aa bb cc dd 00",
            2,
            &[0xaa, 0xbb, 0xcc, 0xdd],
            &[0x11, 0x22, 0x33, 0x44],
        )]);
        let resolved = resolve_with_bank(&table, &bytes, Some(&bank)).unwrap();
        assert_eq!(resolved[0].offset, 0x150);
        assert!(resolved[0].reason.is_none());
    }

    #[test]
    fn unique_original_bytes_relocate_the_site() {
        let table = table(vec![offset_site(
            "site",
            0x100,
            &[0xaa, 0xbb, 0xcc, 0xdd],
            &[0x11, 0x22, 0x33, 0x44],
        )]);
        let mut bytes = vec![0u8; 0x200];
        bytes[0x150..0x154].copy_from_slice(&[0xaa, 0xbb, 0xcc, 0xdd]);
        let resolved = resolve_with_bank(&table, &bytes, None).unwrap();
        assert_eq!(resolved[0].offset, 0x150);
        assert!(resolved[0].reason.is_none());
    }

    #[test]
    fn relative_anchor_relocates_a_duplicate_site() {
        let table = table(vec![
            offset_site(
                "a",
                0x100,
                &[0xaa, 0xbb, 0xcc, 0xdd],
                &[0x11, 0x22, 0x33, 0x44],
            ),
            offset_site(
                "b",
                0x200,
                &[0xdd, 0xee, 0xff, 0x11],
                &[0x55, 0x66, 0x77, 0x88],
            ),
        ]);
        let mut bytes = vec![0u8; 0x400];
        bytes[0x150..0x154].copy_from_slice(&[0xaa, 0xbb, 0xcc, 0xdd]);
        bytes[0x250..0x254].copy_from_slice(&[0xdd, 0xee, 0xff, 0x11]);
        bytes[0x300..0x304].copy_from_slice(&[0xdd, 0xee, 0xff, 0x11]);
        let resolved = resolve_with_bank(&table, &bytes, None).unwrap();
        assert_eq!(resolved[0].offset, 0x150);
        assert_eq!(resolved[1].offset, 0x250);
        assert!(resolved[1].reason.is_none());
    }

    #[test]
    #[ignore = "needs STEREO_TEST_NODE_1281 pointing at a real Windows 1281 node"]
    fn resolves_the_1281_fixture() {
        let Ok(path) = std::env::var("STEREO_TEST_NODE_1281") else {
            return;
        };
        let bytes = std::fs::read(path).expect("read fixture");
        let db =
            crate::tables::parse_db(include_str!("../../patchdb/tables.json")).expect("parse db");
        let table = db
            .tables
            .iter()
            .find(|table| {
                table.goal == "v6"
                    && table.binary_md5.as_deref() == Some("0ebc96a7f0dde80d1866d4cf61eb49cd")
            })
            .expect("v6 9266 table");
        let resolved = resolve(table, &bytes).expect("resolve fixture");
        assert_eq!(resolved.len(), table.sites.len());
        assert!(
            resolved.iter().all(|site| site.reason.is_none()),
            "unresolved sites: {:?}",
            resolved
                .iter()
                .filter(|site| site.reason.is_some())
                .map(|site| (&site.name, &site.reason))
                .collect::<Vec<_>>()
        );
    }

    #[test]
    #[ignore = "needs STEREO_TEST_NODE_9267 pointing at a real Windows 9267 node"]
    fn resolves_the_9267_fixture_at_finder_offsets() {
        let Ok(path) = std::env::var("STEREO_TEST_NODE_9267") else {
            return;
        };
        let bytes = std::fs::read(path).expect("read fixture");
        let db =
            crate::tables::parse_db(include_str!("../../patchdb/tables.json")).expect("parse db");
        let table = db
            .tables
            .iter()
            .find(|table| {
                table.goal == "v6"
                    && table.binary_md5.as_deref() == Some("6f0c4c13d83e94b815211cb5867e8025")
            })
            .expect("v6 9267 table");
        let resolved = resolve(table, &bytes).expect("resolve fixture");
        let expected = [
            ("CreateAudioFrame_ChannelAssign_Mov", 0x0013d990),
            ("CapturedAudioProcessor_APMBypass_NopJmp", 0x000f10b0),
            ("Krisp NC create bypass (mutex-safe)", 0x000cffc5),
            ("Krisp NC process bypass (mutex-safe)", 0x000d0246),
            ("CommitAudioCodec_ChannelCount_Imm02", 0x006824b7),
            ("OpusSdp_StereoValueBypass_Jmp2", 0x006824e6),
            ("ApplySettings_BitrateBase_Mov510k", 0x006828ea),
            ("ApplySettings_BitrateSelect_Nop4", 0x006828f0),
            ("ApplySettings_BitrateChannels_Nop4", 0x006828f4),
            ("SetTargetBitrate_Mulss_Nop6", 0x00684a4e),
            ("OpusSdp_MaxPlaybackRate_Keep48k_Nop4", 0x0068261e),
            ("HighPassFilter_Process_Entry_Ret", 0x0068eb30),
            ("CELT_Force", 0x00aa4688),
            ("CELT_DefaultMode", 0x00aa4704),
            ("SetTargetBitrate_ClampSelect_Nop3", 0x006849ec),
            ("ApplySettings_MaxAvgBitrateSelect_Nop4", 0x006829d7),
            ("OpusEncodeNative_AnalysisGate_Jmp", 0x00aa5209),
            ("OpusEncodeFrame_FilterBypass_CopyGain", 0x00aa70d9),
            ("OpusEncoder_Init_ForceCBR", 0x00aa463f),
            ("OpusEncoder_SetVBR_ForceCBR", 0x00aa9e57),
        ];
        for (name, offset) in expected {
            let site = resolved
                .iter()
                .find(|site| site.name == name)
                .unwrap_or_else(|| panic!("missing site {name}"));
            assert_eq!(site.offset, offset, "{name}");
            assert!(site.reason.is_none(), "{name}: {:?}", site.reason);
        }
    }

    #[test]
    fn ambiguous_original_bytes_stay_unresolved() {
        let table = table(vec![offset_site(
            "site",
            0x100,
            &[0xaa, 0xbb, 0xcc, 0xdd],
            &[0x11, 0x22, 0x33, 0x44],
        )]);
        let mut bytes = vec![0u8; 0x300];
        bytes[0x150..0x154].copy_from_slice(&[0xaa, 0xbb, 0xcc, 0xdd]);
        bytes[0x200..0x204].copy_from_slice(&[0xaa, 0xbb, 0xcc, 0xdd]);
        let resolved = resolve_with_bank(&table, &bytes, None).unwrap();
        assert!(resolved[0].reason.is_some());
    }
}
